CREATE TABLE `catalog_pages`
(
    `id`                    int(11)      NOT NULL AUTO_INCREMENT,
    `parent_id`             int(11)      NOT NULL DEFAULT -1,
    `name`                  varchar(100) NOT NULL,
    `code_name`             varchar(100) NOT NULL,
    `icon_image`            int(11)      NOT NULL DEFAULT 1,
    `visible`               tinyint(1)   NOT NULL DEFAULT 1,
    `enabled`               tinyint(1)   NOT NULL DEFAULT 1,
    `min_rank`              int(11)      NOT NULL DEFAULT 1,
    `club_only`             tinyint(1)   NOT NULL DEFAULT 0,
    `order_num`             int(11)      NOT NULL DEFAULT 1,
    `page_layout`           varchar(100) NOT NULL DEFAULT 'default_3x3',
    `page_headline`         varchar(100) NOT NULL,
    `page_teaser`           varchar(100) NOT NULL,
    `page_special`          text         NOT NULL,
    `page_text1`            text         NOT NULL,
    `page_text2`            text         NOT NULL,
    `page_text_details`     text         NOT NULL,
    `page_text_teaser`      text         NOT NULL,
    `page_link_description` text         NOT NULL,
    `page_link_pagename`    text         NOT NULL,
    PRIMARY KEY (`id`),
    KEY `parent_id` (`parent_id`),
    KEY `order_num` (`order_num`),
    CONSTRAINT `catalog_pages_ibfk_1` FOREIGN KEY (`parent_id`) REFERENCES `catalog_pages` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB
  AUTO_INCREMENT = 80
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_unicode_520_ci
  ROW_FORMAT = COMPRESSED;
